changeSet.sql:
DO $$
BEGIN
    IF EXISTS (
        SELECT 1 FROM pg_indexes 
        WHERE schemaname = 'public' AND indexname = 'uk_menu_category_mapping_menu_category'
    ) THEN
        EXECUTE 'DROP INDEX public.uk_menu_category_mapping_menu_category';
    END IF;
END;
$$;

DO $$
BEGIN
    IF EXISTS (
        SELECT 1 
        FROM information_schema.columns 
        WHERE table_name='menu_category_mapping' AND column_name='id'
    ) THEN
        DELETE FROM menu_category_mapping t
        USING menu_category_mapping d
        WHERE t.menu_id = d.menu_id
          AND t.category_id = d.category_id
          AND t.ctid > d.ctid;
    END IF;
END;
$$;

DO $$
DECLARE pk_name text;
BEGIN
    SELECT tc.constraint_name INTO pk_name
    FROM information_schema.table_constraints tc
    WHERE tc.table_schema='public' AND tc.table_name='menu_category_mapping' AND tc.constraint_type='PRIMARY KEY'
    LIMIT 1;
    IF pk_name IS NOT NULL THEN
        EXECUTE format('ALTER TABLE public.menu_category_mapping DROP CONSTRAINT %I', pk_name);
    END IF;
END;
$$;

DO $$
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM information_schema.columns 
        WHERE table_name='menu_category_mapping' AND column_name='id'
    ) THEN
        ALTER TABLE public.menu_category_mapping ADD COLUMN id UUID;
    END IF;
END;
$$;
